  text-transform: uppercase;
  font-size: 0.8125rem;
  border: none;
  position: relative;
}

.btn--link::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0;
  width: 0;
  height: 1px;
  background: var(--gold);
  transition: width var(--transition-base);
}

.btn--link:hover::after {
  width: 100%;
}

.btn--link:hover {
  color: var(--gold-light);
}

.btn--link-white {
  color: var(--white);
}

.btn--link-white::after {
  background: var(--white);
}

.btn--link-white:hover {
  color: var(--gold-light);
}

/* --- Header & Navigation --- */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: var(--navy);
  height: 72px;
  transition: background var(--transition-base), box-shadow var(--transition-base);
}

.header.scrolled {
  background: rgba(10, 22, 40, 0.97);
  box-shadow: 0 2px 20px rgba(0,0,0,0.3);
}

.header__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.header__logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--white);
  letter-spacing: 0.02em;
  z-index: 1001;
}

.header__logo-icon {
  width: 32px;
  height: 32px;
  background: var(--gold);
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

.header__logo-icon::after {
  content: '';
  width: 14px;
  height: 14px;
  background: var(--navy);
}

/* Desktop Nav */
.nav-desktop {
  display: none;
  align-items: center;
  gap: 0;
  height: 100%;
}

@media (min-width: 1024px) {
  .nav-desktop { display: flex; }
}

.nav-desktop__item {
  position: relative;
  height: 72px;
  display: flex;
  align-items: center;
}

.nav-desktop__link {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 0 18px;
  height: 100%;
  color: var(--gray-300);
  font-size: 0.875rem;
  font-weight: 500;
  letter-spacing: 0.02em;
  transition: color var(--transition-fast);
  white-space: nowrap;
}

.nav-desktop__link:hover,
.nav-desktop__link.active {
  color: var(--white);
}

.nav-desktop__link .arrow {
  font-size: 0.625rem;
  transition: transform var(--transition-fast);
}

.nav-desktop__item:hover .arrow,
.nav-desktop__item.open .arrow {
  transform: rotate(180deg);
}

/* Mega Menu */
.mega-menu {
  position: absolute;
  top: 72px;
  left: 50%;
  transform: translateX(-50%);
  width: 680px;
  background: var(--white);
  box-shadow: var(--shadow-xl);
  border-top: 3px solid var(--gold);
  padding: 32px 40px;
  display: none;
  opacity: 0;
  visibility: hidden;
  transition: opacity var(--transition-base), visibility var(--transition-base);
}

.nav-desktop__item:hover .mega-menu,
.nav-desktop__item.open .mega-menu {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
  opacity: 1;
  visibility: visible;
}

.mega-menu__column-title {
  font-family: var(--font-body);
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--gold);
  margin-bottom: 16px;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--gray-200);
}

.mega-menu__link {
  display: block;
  padding: 8px 0;
  color: var(--gray-700);
  font-size: 0.9rem;
  font-weight: 500;
  transition: color var(--transition-fast), padding-left var(--transition-fast);
}

.mega-menu__link:hover {
  color: var(--navy);
  padding-left: 6px;
}

.mega-menu__link-desc {
  font-size: 0.78rem;
  color: var(--gray-400);
  font-weight: 400;
  margin-top: 2px;
}

/* Mobile Nav Toggle */
.nav-toggle {
  display: flex;
  flex-direction: column;
  gap: 5px;
  width: 28px;
  height: 28px;
  justify-content: center;
  z-index: 1001;
}

@media (min-width: 1024px) {
  .nav-toggle { display: none; }
}

.nav-toggle span {
  display: block;
  width: 100%;
  height: 2px;
  background: var(--white);
  transition: all var(--transition-base);
  transform-origin: center;
}

.nav-toggle.active span:nth-child(1) {
  transform: translateY(7px) rotate(45deg);
}

.nav-toggle.active span:nth-child(2) {
  opacity: 0;
}

.nav-toggle.active span:nth-child(3) {
  transform: translateY(-7px) rotate(-45deg);
}

/* Mobile Nav */
.nav-mobile {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--navy);
  z-index: 1000;
  padding: 100px 24px 40px;
  overflow-y: auto;
  transform: translateX(100%);
  transition: transform var(--transition-base);
}

.nav-mobile.active {
  transform: translateX(0);
}

.nav-mobile__item {
  border-bottom: 1px solid rgba(255,255,255,0.08);
}

.nav-mobile__link {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 0;
  color: var(--white);
  font-size: 1.125rem;
  font-weight: 500;
}

.nav-mobile__link .arrow {
  font-size: 0.75rem;
  transition: transform var(--transition-fast);
}

.nav-mobile__item.open .arrow {
  transform: rotate(180deg);
}

.nav-mobile__sub {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow);
}

.nav-mobile__item.open .nav-mobile__sub {
  max-height: 600px;
}

.nav-mobile__sub-title {
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--gold);
  padding: 12px 0 8px;
}

.nav-mobile__sub-link {
  display: block;
  padding: 10px 0 10px 16px;
  color: var(--gray-300);
  font-size: 0.9375rem;
  transition: color var(--transition-fast);
}

.nav-mobile__sub-link:hover {
  color: var(--white);
}

/* --- Hero Section --- */
.hero {
  position: relative;
  min-height: 520px;
  display: flex;
  align-items: flex-end;
  padding: 120px 0 60px;
  margin-top: 72px;
  overflow: hidden;
}

.hero__bg {
  position: absolute;
  inset: 0;
  z-index: 0;
}

.hero__bg-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.hero__overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(10,22,40,0.88) 0%, rgba(1,42,45,0.75) 100%);
  z-index: 1;
}

.hero__content {
  position: relative;
  z-index: 2;
  max-width: 680px;
}

.hero__label {
  display: inline-block;
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--gold);
  margin-bottom: 16px;
}

.hero h1 {
  color: var(--white);
  margin-bottom: 20px;
  font-size: clamp(2rem, 4.5vw, 3.25rem);
}

.hero__subtitle {
  font-size: 1.125rem;
  color: var(--gray-300);
  line-height: 1.6;
  margin-bottom: 32px;
  max-width: 560px;
}

.hero--compact {
  min-height: 360px;
  padding: 100px 0 48px;
}

.hero--compact h1 {
  font-size: clamp(1.75rem, 3.5vw, 2.75rem);
}

/* Placeholder image backgrounds */
.hero__bg--skyscrapers {
  background: linear-gradient(135deg, #1a2a4a 0%, #0a1628 30%, #162a3a 60%, #0d2233 100%);
}

.hero__bg--invest {
  background: linear-gradient(135deg, #0a1628 0%, #012a2d 50%, #0a1628 100%);
}

.hero__bg--plan {
  background: linear-gradient(135deg, #0d1f35 0%, #012a2d 50%, #0a1628 100%);
}

.hero__bg--design {
  background: linear-gradient(135deg, #162035 0%, #012a2d 60%, #0a1628 100%);
}

.hero__bg--services {
  background: linear-gradient(135deg, #0a1628 0%, #0d2a35 50%, #012a2d 100%);
}

/* Decorative shapes for hero backgrounds */
.hero__bg--skyscrapers::before {
  content: '';
  position: absolute;
  top: 15%;
  right: 8%;
  width: 280px;
  height: 350px;
  background: rgba(197,165,114,0.04);
  clip-path: polygon(0 100%, 50% 0, 100% 100%);
}

.hero__bg--skyscrapers::after {
  content: '';
  position: absolute;
  top: 20%;
  right: 15%;
  width: 200px;
  height: 280px;
  background: rgba(197,165,114,0.06);
  clip-path: polygon(0 100%, 50% 0, 100% 100%);
}

/* --- Featured Insights --- */
.featured-insights {
  padding: 56px 0;
}

.featured-insights__grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
}

@media (min-width: 768px) {
  .featured-insights__grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.featured-insight-card {
  position: relative;
  border-radius: 2px;
  overflow: hidden;
  transition: transform var(--transition-base), box-shadow var(--transition-base);
  background: var(--gray-50);
}

.featured-insight-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.featured-insight-card__img {
  height: 200px;
  overflow: hidden;
}

.featured-insight-card__img-bg {
  width: 100%;
  height: 100%;
  background: linear-gradient(135deg, var(--navy) 0%, var(--teal) 100%);
  transition: transform var(--transition-slow);
}

.featured-insight-card:hover .featured-insight-card__img-bg {
  transform: scale(1.05);
}

.featured-insight-card__tag {
  position: absolute;
  top: 16px;
  left: 16px;
  background: var(--gold);
  color: var(--navy);
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  padding: 4px 10px;
}

.featured-insight-card__body {
  padding: 24px;
}

.featured-insight-card__title {
  font-size: 1.0625rem;
  font-weight: 600;
  color: var(--navy);
  margin-bottom: 12px;
  line-height: 1.4;
}

.featured-insight-card__title:hover {
  color: var(--teal-accent);
}

/* --- Announcement Banner --- */
.announcement-banner {
  background: var(--teal);
  padding: 28px 0;
}

.announcement-banner__inner {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 16px;
}

@media (min-width: 768px) {
  .announcement-banner__inner {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
  }
}

.announcement-banner__text {
  color: var(--white);
  font-size: 1.0625rem;
  font-weight: 500;
}

.announcement-banner__cta {
  flex-shrink: 0;
}

/* --- About Statement --- */
.about-statement {
  padding: var(--section-padding);
}

.about-statement__inner {
  display: grid;
  grid-template-columns: 1fr;
  gap: 32px;
  align-items: center;
}

@media (min-width: 768px) {
  .about-statement__inner {
    grid-template-columns: 1fr 1fr;
    gap: 64px;
  }
}

.about-statement__label {
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--gold);
  margin-bottom: 16px;
}

.about-statement__text {
  font-size: 1.25rem;
  line-height: 1.7;
  color: var(--gray-700);
}

.about-statement__visual {
  position: relative;
  height: 320px;
  background: linear-gradient(135deg, var(--navy) 0%, var(--teal) 100%);
  border-radius: 2px;
  overflow: hidden;
}

.about-statement__visual::after {
  content: '';
  position: absolute;
  top: 20%;
  left: 50%;
  transform: translateX(-50%);
  width: 200px;
  height: 200px;
  background: rgba(197,165,114,0.08);
  border-radius: 50%;
}

/* --- What We Do (Tabbed Section) --- */
.what-we-do {
  padding: var(--section-padding);
  background: var(--gray-50);
}

.what-we-do__header {
  text-align: center;
  margin-bottom: 48px;
}

.what-we-do__inner {
  display: grid;
  grid-template-columns: 1fr;
  gap: 32px;
}

@media (min-width: 768px) {
  .what-we-do__inner {
    grid-template-columns: 240px 1fr;
    gap: 0;
  }
}

.what-we-do__tabs {
  display: flex;
  flex-direction: row;
  gap: 0;
  overflow-x: auto;
}

@media (min-width: 768px) {
  .what-we-do__tabs {
    flex-direction: column;
    border-right: 1px solid var(--gray-200);
  }
}

.what-we-do__tab {
  padding: 16px 24px;
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--gray-500);
  background: transparent;
  border: none;
  text-align: left;
  cursor: pointer;
  transition: all var(--transition-fast);
  white-space: nowrap;
  position: relative;
  border-bottom: 2px solid transparent;
}

@media (min-width: 768px) {
  .what-we-do__tab {
    border-bottom: none;
    border-right: 3px solid transparent;
  }
}

.what-we-do__tab:hover {
  color: var(--navy);
}

.what-we-do__tab.active {
  color: var(--navy);
  font-weight: 600;
  border-bottom-color: var(--gold);
}

@media (min-width: 768px) {
  .what-we-do__tab.active {
    border-bottom-color: transparent;
    border-right-color: var(--gold);
    background: var(--white);
  }
}

.what-we-do__panel {
  display: none;
  padding: 24px 0 0;
}

@media (min-width: 768px) {
  .what-we-do__panel {
    padding: 0 0 0 48px;
  }
}

.what-we-do__panel.active {
  display: block;
}

.what-we-do__panel h3 {
  margin-bottom: 16px;
}

.what-we-do__panel p {
  font-size: 1.0625rem;
  line-height: 1.7;
  margin-bottom: 24px;
}

.what-we-do__panel-list {
  margin-bottom: 24px;
}

.what-we-do__panel-list li {
  padding: 6px 0;
  color: var(--gray-600);
  font-size: 0.9375rem;
  display: flex;
  align-items: center;
  gap: 8px;
}

.what-we-do__panel-list li::before {
  content: '';
  width: 6px;
  height: 6px;
  background: var(--gold);
  flex-shrink: 0;
}

/* --- Newsletter --- */
.newsletter {
  padding: var(--section-padding);
}

.newsletter__inner {
  max-width: 560px;
  margin: 0 auto;
  text-align: center;
}

.newsletter__icon {
  width: 56px;
  height: 56px;
  background: var(--gold);
  margin: 0 auto 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  color: var(--navy);
  border-radius: 50%;
}

.newsletter h2 {
  margin-bottom: 12px;
}

.newsletter__subtitle {
  color: var(--gray-500);
  margin-bottom: 32px;
  font-size: 1.0625rem;
}

.newsletter__form {
  display: flex;
  gap: 12px;
  max-width: 460px;
  margin: 0 auto;
}

.newsletter__input {
  flex: 1;
  padding: 14px 18px;
  border: 1px solid var(--gray-300);
  font-family: var(--font-body);
  font-size: 0.9375rem;
  border-radius: 2px;
  transition: border-color var(--transition-fast);
}

.newsletter__input:focus {
  outline: none;
  border-color: var(--gold);
}

/* --- Latest Insights --- */
.latest-insights {
  padding: var(--section-padding);
  background: var(--gray-50);
}

.latest-insights__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 40px;
}

.latest-insights__grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
}

@media (min-width: 768px) {
  .latest-insights__grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.insight-card {
  background: var(--white);
  border-radius: 2px;
  overflow: hidden;
  transition: transform var(--transition-base), box-shadow var(--transition-base);
  border: 1px solid var(--gray-200);
}

.insight-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-md);
}

.insight-card__img {
  height: 180px;
  background: linear-gradient(135deg, var(--navy) 0%, var(--teal) 100%);
  position: relative;
  overflow: hidden;
}

.insight-card__img::after {
  content: '';
  position: absolute;
  inset: 0;
  background: rgba(10,22,40,0.15);
}

.insight-card__category {
  position: absolute;
  bottom: 12px;
  left: 12px;
  background: rgba(10,22,40,0.85);
  color: var(--gold);
  font-size: 0.6875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 4px 10px;
  z-index: 1;
}

.insight-card__body {
  padding: 20px;
}

.insight-card__title {
  font-size: 1rem;
  font-weight: 600;
  color: var(--navy);
  margin-bottom: 12px;
  line-height: 1.4;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.insight-card__title:hover {
  color: var(--teal-accent);
}

.insight-card__date {
  font-size: 0.8125rem;
  color: var(--gray-400);
}

/* --- Our Commitment --- */
.our-commitment {
  padding: var(--section-padding);
}

.our-commitment__grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
}

@media (min-width: 768px) {
  .our-commitment__grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .our-commitment__grid {
    grid-template-columns: repeat(4, 1fr);
  }
}

.commitment-card {
  padding: 32px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 2px;
  transition: all var(--transition-base);
}

.commitment-card:hover {
  border-color: var(--gold);
  box-shadow: var(--shadow-md);
}

.commitment-card__icon {
  width: 40px;
  height: 40px;
  background: var(--navy);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
  color: var(--gold);
  font-size: 1.125rem;
}

.commitment-card__title {
  font-size: 1.0625rem;
  font-weight: 600;
  color: var(--navy);
  margin-bottom: 12px;
}

.commitment-card__text {
  font-size: 0.9rem;
  color: var(--gray-500);
  line-height: 1.6;
  margin-bottom: 20px;
}

/* --- Services Overview --- */
.service-category-card {
  padding: 36px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 2px;
  transition: all var(--transition-base);
  display: flex;
  flex-direction: column;
}

.service-category-card:hover {
  border-color: var(--gold);
  box-shadow: var(--shadow-md);
  transform: translateY(-3px);
}

.service-category-card__number {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 300;
  color: var(--gray-200);
  margin-bottom: 16px;
  line-height: 1;
}

.service-category-card__title {
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--navy);
  margin-bottom: 12px;
}

.service-category-card__desc {
  font-size: 0.9375rem;
  color: var(--gray-500);
  line-height: 1.6;
  margin-bottom: 24px;
  flex: 1;
}

.service-categories__grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
}

@media (min-width: 768px) {
  .service-categories__grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .service-categories__grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

/* --- Capabilities Grid --- */
.capabilities-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
}

@media (min-width: 768px) {
  .capabilities-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .capabilities-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.capability-card {
  padding: 32px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 2px;
  transition: all var(--transition-base);
}

.capability-card:hover {
  border-color: var(--gold);
  box-shadow: var(--shadow-md);
}

.capability-card__icon {
  width: 44px;
  height: 44px;
  background: var(--navy);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
  color: var(--gold);
  font-size: 1.125rem;
}

.capability-card__title {
  font-family: var(--font-body);
  font-size: 1.0625rem;
  font-weight: 600;
  color: var(--navy);
  margin-bottom: 10px;
}

.capability-card__desc {
  font-size: 0.9rem;
  color: var(--gray-500);
  line-height: 1.6;
  margin-bottom: 16px;
}

/* --- Featured Partners Carousel --- */
.featured-partners {
  padding: var(--section-padding);
  background: var(--gray-50);
}

.carousel {
  position: relative;
  overflow: hidden;
}

.carousel__track {
  display: flex;
  transition: transform var(--transition-slow);
}

.carousel__slide {
  min-width: 100%;
  padding: 40px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 2px;
}

.carousel__quote {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-style: italic;
  color: var(--gray-700);
  line-height: 1.6;
  margin-bottom: 24px;
}

.carousel__author {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--navy);
}

.carousel__role {
  font-size: 0.8125rem;
  color: var(--gray-400);
}

.carousel__controls {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-top: 24px;
}

.carousel__btn {
  width: 44px;
  height: 44px;
  border: 1px solid var(--gray-300);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.125rem;
  color: var(--gray-600);
  transition: all var(--transition-fast);
  border-radius: 50%;
}

.carousel__btn:hover {
  border-color: var(--navy);
  color: var(--navy);
  background: var(--gray-50);
}

.carousel__dots {
  display: flex;
  gap: 8px;
}

.carousel__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--gray-300);
  cursor: pointer;
  transition: background var(--transition-fast);
}

.carousel__dot.active {
  background: var(--gold);
  width: 24px;
  border-radius: 4px;
}

/* --- Deal Flow CTA --- */
.deal-flow-cta {
  padding: 64px 0;
  background: var(--navy);
  text-align: center;
}

.deal-flow-cta h2 {
  color: var(--white);
  margin-bottom: 16px;
}

.deal-flow-cta p {
  color: var(--gray-300);
  max-width: 560px;
  margin: 0 auto 32px;
  font-size: 1.0625rem;
}

/* --- Testimonial --- */
.testimonial {
  padding: var(--section-padding);
}

.testimonial__inner {
  max-width: 720px;
  margin: 0 auto;
  text-align: center;
}

.testimonial__quote {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-style: italic;
  color: var(--navy);
  line-height: 1.6;
  margin-bottom: 24px;
}

.testimonial__author {
  font-weight: 600;
  color: var(--navy);
}

.testimonial__role {
  font-size: 0.875rem;
  color: var(--gray-400);
}

/* --- Featured Topics Sidebar --- */
.featured-topics {
  padding: 32px;
  background: var(--gray-50);
  border-radius: 2px;
}

.featured-topics__title {
  font-family: var(--font-body);
  font-size: 0.8125rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--gold-dark);
  margin-bottom: 16px;
}

.featured-topics__list li {
  padding: 10px 0;
  border-bottom: 1px solid var(--gray-200);
}

.featured-topics__list li:last-child {
  border-bottom: none;
}

.featured-topics__link {
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: var(--navy);
  font-size: 0.9375rem;
  font-weight: 500;
}

.featured-topics__link:hover {
  color: var(--gold-dark);
}

/* --- Property Types CTA --- */
.property-types-cta {
  padding: var(--section-padding);
  background: var(--gray-50);
}

.property-types-cta__grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
}

@media (min-width: 768px) {
  .property-types-cta__grid {
    grid-template-columns: repeat(5, 1fr);
  }
}

.property-type-card {
  padding: 24px 16px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  text-align: center;
  transition: all var(--transition-base);
  border-radius: 2px;
}

.property-type-card:hover {
  border-color: var(--gold);
  transform: translateY(-2px);
  box-shadow: var(--shadow-sm);
}

.property-type-card__name {
  font-weight: 600;
  font-size: 0.9375rem;
  color: var(--navy);
}

/* --- Related Services --- */
.related-services {
  padding: var(--section-padding);
}

.related-services__grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 16px;
}

@media (min-width: 768px) {
  .related-services__grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.related-service-card {
  padding: 24px;
  background: var(--gray-50);
  border-radius: 2px;
  transition: all var(--transition-fast);
}

.related-service-card:hover {
  background: var(--white);
  box-shadow: var(--shadow-sm);
}

.related-service-card__title {
  font-size: 1rem;
  font-weight: 600;
  color: var(--navy);
  margin-bottom: 8px;
}

.related-service-card__desc {
  font-size: 0.85rem;
  color: var(--gray-500);
  margin-bottom: 12px;
}

/* --- Related Insights --- */
.related-insights {
  padding: var(--section-padding);
  background: var(--gray-50);
}

/* --- Partnership Highlight --- */
.partnership-highlight {
  padding: var(--section-padding);
}

.partnership-highlight__inner {
  display: grid;
  grid-template-columns: 1fr;
  gap: 40px;
  align-items: center;
}

@media (min-width: 768px) {
  .partnership-highlight__inner {
    grid-template-columns: 1fr 1fr;
    gap: 64px;
  }
}

.partnership-highlight__stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
  margin-top: 32px;
}

.partnership-highlight__stat {
  text-align: center;
  padding: 24px;
  background: var(--gray-50);
  border-radius: 2px;
}

.partnership-highlight__stat-value {
  font-family: var(--font-heading);
  font-size: 2rem;
  font-weight: 700;
  color: var(--gold);
  margin-bottom: 4px;
}

.partnership-highlight__stat-label {
  font-size: 0.8125rem;
  color: var(--gray-500);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.partnership-highlight__visual {
  height: 360px;
  background: linear-gradient(135deg, var(--navy) 0%, var(--teal) 100%);
  border-radius: 2px;
  position: relative;
  overflow: hidden;
}

.partnership-highlight__visual::before {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 200px;
  height: 200px;
  border: 2px solid rgba(197,165,114,0.15);
  border-radius: 50%;
}

.partnership-highlight__visual::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 120px;
  height: 120px;
  border: 2px solid rgba(197,165,114,0.25);
  border-radius: 50%;
}

/* --- Footer --- */
.footer {
  background: var(--navy);
  padding: 64px 0 32px;
  color: var(--gray-300);
}

.footer__grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 40px;
  margin-bottom: 48px;
}

@media (min-width: 768px) {
  .footer__grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .footer__grid {
    grid-template-columns: 2fr 1fr 1fr 1fr;
  }
}

.footer__brand-desc {
  font-size: 0.9rem;
  color: var(--gray-400);
  line-height: 1.7;
  margin-top: 16px;
  max-width: 320px;
}

.footer__heading {
  font-family: var(--font-body);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--gold);
  margin-bottom: 20px;
}

.footer__link {
  display: block;
  padding: 6px 0;
  font-size: 0.875rem;
  color: var(--gray-400);
  transition: color var(--transition-fast);
}

.footer__link:hover {
  color: var(--white);
}

.footer__bottom {
  border-top: 1px solid rgba(255,255,255,0.08);
  padding-top: 24px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

@media (min-width: 768px) {
  .footer__bottom {
    flex-direction: row;
    justify-content: space-between;
    align-items: center;
  }
}

.footer__legal {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
}

.footer__legal a {
  font-size: 0.8125rem;
  color: var(--gray-500);
  transition: color var(--transition-fast);
}

.footer__legal a:hover {
  color: var(--white);
}

.footer__copyright {
  font-size: 0.8125rem;
  color: var(--gray-500);
}

/* --- Intro Statement --- */
.intro-statement {
  padding: var(--section-padding);
  text-align: center;
}

.intro-statement__inner {
  max-width: 720px;
  margin: 0 auto;
}

.intro-statement__text {
  font-size: 1.25rem;
  line-height: 1.7;
  color: var(--gray-600);
}

/* --- Section Header --- */
.section-header {
  margin-bottom: 40px;
}

.section-header__label {
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--gold);
  margin-bottom: 12px;
}

.section-header h2 {
  margin-bottom: 12px;
}

.section-header__desc {
  font-size: 1.0625rem;
  color: var(--gray-500);
  max-width: 560px;
}

.section-header--center {
  text-align: center;
}

.section-header--center .section-header__desc {
  margin: 0 auto;
}

/* --- Content with Sidebar --- */
.content-with-sidebar {
  display: grid;
  grid-template-columns: 1fr;
  gap: 40px;
}

@media (min-width: 1024px) {
  .content-with-sidebar {
    grid-template-columns: 1fr 280px;
  }
}

/* --- Utility --- */
.text-gold { color: var(--gold); }
.text-white { color: var(--white); }
.mt-0 { margin-top: 0; }
.mb-0 { margin-bottom: 0; }
.mb-sm { margin-bottom: 8px; }
.mb-md { margin-bottom: 16px; }
.mb-lg { margin-bottom: 24px; }
.mb-xl { margin-bottom: 40px; }

/* --- Animations --- */
@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.animate-in {
  opacity: 0;
  transform: translateY(20px);
  transition: opacity 0.6s ease, transform 0.6s ease;
}

.animate-in.visible {
  opacity: 1;
  transform: translateY(0);
}

/* --- Print Styles --- */
@media print {
  .header, .footer, .nav-mobile, .nav-toggle {
    display: none !important;
  }
  .hero {
    margin-top: 0;
    min-height: auto;
    padding: 40px 0;
  }
}
