  border-bottom-color: var(--gold);
}

@media (min-width: 768px) {
  .what-we-do__tab.active {
    border-bottom-color: transparent;
    border-right-color: var(--gold);
    background: var(--white);
  }
}

.what-we-do__panel {
  display: none;
  padding: 24px 0 0;
}

@media (min-width: 768px) {
  .what-we-do__panel {
    padding: 0 0 0 48px;
  }
}

.what-we-do__panel.active {
  display: block;
}

.what-we-do__panel h3 {
  margin-bottom: 16px;
}

.what-we-do__panel p {
  font-size: 1.0625rem;
  line-height: 1.7;
  margin-bottom: 24px;
}

.what-we-do__panel-list {
