  align-items: center;
  gap: 8px;
}

.what-we-do__panel-list li::before {
  content: '';
  width: 6px;
  height: 6px;
  background: var(--gold);
  flex-shrink: 0;
}

/* --- Newsletter --- */
.newsletter {
  padding: var(--section-padding);
}

.newsletter__inner {
  max-width: 560px;
  margin: 0 auto;
  text-align: center;
}

.newsletter__icon {
  width: 56px;
  height: 56px;
  background: var(--gold);
